style.css:
@-moz-document domain("roblox.com") {
/* Main Background */
  body {
    background-image: url("https://i.imgur.com/Rnrz083.png");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center center;
    font-family: "Poppins", sans-serif;
    color: #fce4ec !important;
    background-color: #1a001f !important;
    overflow-x: hidden;
  }

  /* Sparkle Overlay */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100vw; height: 100vh;
    pointer-events: none;
    background: url("https://i.imgur.com/V6ZfhkI.png"); /* sparkle pattern image (transparent) */
    animation: sparkleScroll 40s linear infinite;
    z-index: 9999;
    opacity: 0.5;
  }

  @keyframes sparkleScroll {
    0% { background-position: 0 0; }
    100% { background-position: 1000px 1000px; }
  }

  /* Header */
  .header-container, .navbar, .navigation-container {
    background-color: rgba(88, 0, 117, 0.8) !important;
    backdrop-filter: blur(6px);
    color: #f8bbd0 !important;
  }

  /* Navigation Menu */
  .nav-menu, .menu-container, .dropdown-menu, .menu-content {
    background-color: rgba(139, 0, 139, 0.6) !important;
    color: #ffe6f2 !important;
    border-radius: 12px;
  }

  /* Buttons */
  .btn-play-game, .btn-primary, button[aria-label="Play"] {
    background-color: #b0006d !important;
    border: none !important;
    color: white !important;
    border-radius: 12px !important;
    padding: 10px 20px;
    font-weight: bold;
    box-shadow: 0 0 10px #ff69b4;
    transition: transform 0.2s ease-in-out;
  }

  .btn-play-game:hover,
  .btn-primary:hover {
    transform: scale(1.05);
    background-color: #d63384 !important;
  }

  /* Cards & Containers */
  .card, .content, .container, .section {
    background-color: rgba(32, 0, 48, 0.8) !important;
    color: #fce4ec !important;
    border-radius: 10px;
  }

  /* Custom Cursor */
  * {
    cursor: url("https://cur.cursors-4u.net/cursors/cur-13/cur1167.cur"), auto !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #300036;
  }
  ::-webkit-scrollbar-thumb {
    background: #b0006d;
    border-radius: 5px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #ff69b4;
  }
}
